//! The wow-api declarations embedded in the compiler (decision T83), until
//! the package manager provides `wow-api-<flavor>` packages (milestone M6).
//! Generated by `cargo xtask types gen`; see `data/`.

/// A generated declaration file.
#[derive(Clone, Copy, Debug)]
pub struct File {
    pub path: &'static str,
    pub text: &'static str,
}

const SHARED: File = File {
    path: "<wow-api>/shared.d.wowlua",
    text: include_str!("../data/shared.d.wowlua"),
};

/// The declarations of a flavor: the shared file and the flavor's own.
pub fn declarations(flavor: &str) -> Option<[File; 2]> {
    let own = match flavor {
        "standard" => File {
            path: "<wow-api>/standard.d.wowlua",
            text: include_str!("../data/standard.d.wowlua"),
        },
        "camelot" => File {
            path: "<wow-api>/camelot.d.wowlua",
            text: include_str!("../data/camelot.d.wowlua"),
        },
        "mists" => File {
            path: "<wow-api>/mists.d.wowlua",
            text: include_str!("../data/mists.d.wowlua"),
        },
        "cata" => File {
            path: "<wow-api>/cata.d.wowlua",
            text: include_str!("../data/cata.d.wowlua"),
        },
        "wrath" => File {
            path: "<wow-api>/wrath.d.wowlua",
            text: include_str!("../data/wrath.d.wowlua"),
        },
        "tbc" => File {
            path: "<wow-api>/tbc.d.wowlua",
            text: include_str!("../data/tbc.d.wowlua"),
        },
        "vanilla" => File {
            path: "<wow-api>/vanilla.d.wowlua",
            text: include_str!("../data/vanilla.d.wowlua"),
        },
        _ => return None,
    };
    Some([SHARED, own])
}
